verification_commands.ac2:
set -u
test -f README.md || { echo "ac2 RED: README.md missing"; exit 1; }
test -f backend/scripts/docs_verification.py || { echo "ac2 RED: backend/scripts/docs_verification.py missing"; exit 1; }
test -f docs/criteria/docs_verification.md || { echo "ac2 RED: docs/criteria/docs_verification.md missing"; exit 1; }
command -v python3 >/dev/null || { echo "ac2 RED: python3 missing"; exit 1; }
CL=$(tr -d '\r' < README.md | wc -l | tr -d " ")
CD=$(tr -d '\r' < README.md | sha256sum | awk '{print $1}')
PINL=$(tr -d '\r' < backend/scripts/docs_verification.py | sed -n 's/^README_LINES = \([0-9][0-9]*\)$/\1/p' | head -1)
PIND=$(tr -d '\r' < backend/scripts/docs_verification.py | sed -n 's/^README_DIGEST = "\([0-9a-f]*\)"$/\1/p' | head -1)
[ -n "$PINL" ] && [ -n "$PIND" ] || { echo "ac2 RED: the README pin constants could not be parsed"; exit 1; }
[ "$CL" = "$PINL" ] || { echo "ac2 RED: README_LINES is $PINL but the candidate measures $CL lines - MEASURE your own README, never copy a number from this card"; exit 1; }
[ "$CD" = "$PIND" ] || { echo "ac2 RED: README_DIGEST is $PIND but the candidate measures $CD - the digest pin must be measured from your own candidate bytes"; exit 1; }
[ "$CD" != "f7c85e88c5e20296fd9de1c540495a3ab17e17d14bea8e9fb4854436424e8664" ] || { echo "ac2 RED: README_DIGEST still pins the survey-base README - t111 exists to move it"; exit 1; }
[ "$PINL" != "396" ] || { echo "ac2 RED: README_LINES still pins the survey-base line count 396 - the pin did not move"; exit 1; }
if git rev-parse --git-dir >/dev/null 2>&1 && git cat-file -e HEAD:README.md 2>/dev/null; then
  OLDD=$(git show HEAD:README.md | tr -d '\r' | sha256sum | awk '{print $1}')
  [ "$CD" != "$OLDD" ] || { echo "ac2 RED: the digest equals README.md at HEAD - either the README was not edited or the constant was left behind"; exit 1; }
  echo "ac2 evidence: the pin moved off this card's own base (HEAD digest $OLDD -> candidate $CD)"
fi
G="docs/criteria/docs_verification.md"
grep -qF "Generated by \`backend/scripts/docs_verification.py\`" "$G" || { echo "ac2 RED: the report lost its generated-by header - it is tool output, never hand-edit it"; exit 1; }
grep -qE "README_MEASURE PASS lines=$CL digest=$CD" "$G" || { echo "ac2 RED: the committed report does not record README_MEASURE PASS for these candidate bytes ($CL/$CD) - regenerate it with the pinned uv environment"; exit 1; }
grep -qE "^\| 1 \| README under 500 lines \| REQ-DOC-010 \| executed \| README_MEASURE \|$" "$G" || { echo "ac2 RED: the REQ-DOC-010 evidence row is not executed"; exit 1; }
grep -qE "LINK_CHECK PASS files=[0-9]+ links=[0-9]+ broken=0" "$G" || { echo "ac2 RED: the link check is not PASS broken=0 - the rewritten section may not introduce a broken relative link"; exit 1; }
grep -qE "^CARRIED_REPORT PASS file=docs/criteria/agent_pack_verification.md rows=22$" "$G" || { echo "ac2 RED: the carried agent_pack row broke - this card does not own that report"; exit 1; }
# envelope that stored legs enforce
[ "$CL" -le 400 ] || { echo "ac2 RED: the candidate README is $CL lines - legs 256 (t71 ac1) and 258 (t71 ac4) assert <= 400 on the root README, so a rewrite past 400 turns two shipped gates RED"; exit 1; }
[ "$CL" -ge 340 ] || { echo "ac2 RED: the candidate README is $CL lines, below the 340 floor legs 256/258 enforce"; exit 1; }
[ "$CL" -lt 500 ] || { echo "ac2 RED: REQ-DOC-010 - README must stay under 500 lines"; exit 1; }
H2=$(tr -d '\r' < README.md | grep -cE "^## [^#]")
[ "$H2" = "17" ] || { echo "ac2 RED: the candidate carries $H2 level-2 headings, not 17 - t111 rewrites sections IN PLACE; the 17->18 transition belongs to t116, which adds the scoring-map H2"; exit 1; }
NL=$(python3 -c "b=open('README.md','rb').read();print(b.count(b'\n'))")
CRLF=$(python3 -c "b=open('README.md','rb').read();print(b.count(b'\r\n'))")
[ "$NL" = "$CRLF" ] || { echo "ac2 RED: $NL newlines but $CRLF CRLF pairs - README.md stays all-CRLF"; exit 1; }
python3 -c "b=open('README.md','rb').read();import sys;sys.exit(0 if all(x<128 for x in b) else 1)" || { echo "ac2 RED: README.md carries a non-ASCII byte"; exit 1; }
REQS=$(tr -d '\r' < README.md | grep -oE "REQ-[A-Z]+-[0-9]+" | sort -u | sha256sum | awk '{print $1}')
[ "$REQS" = "01f3611817b98bd95baa2b709ba8c5e9f32be274d337a5fca8541deeb5413794" ] || { echo "ac2 RED: the README REQ-identifier set changed (sha $REQS) - this card rewords prose and adds and removes no requirement marker, and the 749-row coverage matrix cites README as a source"; exit 1; }
HEX=$(tr -d '\r' < backend/scripts/docs_verification.py | grep -coE "\"[0-9a-f]{64}\"")
[ "$HEX" = "13" ] || { echo "ac2 RED: docs_verification.py carries $HEX 64-hex literals, not 13 - this card may REPLACE the README pin value, never add or remove a pinned literal"; exit 1; }
# CARRIED re-pin absorption (groom addition): the two reports t119 regenerates are
# byte-pinned in docs_verification.py CARRIED_DIGESTS and t111 owns that re-pin.
RD_AP=$(tr -d '\r' < docs/criteria/agent_pack_verification.md | sha256sum | awk '{print $1}')
RD_IF=$(tr -d '\r' < docs/criteria/infra_verification.md | sha256sum | awk '{print $1}')
grep -qF "$RD_AP" backend/scripts/docs_verification.py || { echo "ac2 RED: CARRIED_DIGESTS still pins agent_pack_verification.md at a value other than the committed report ($RD_AP) - t111 runs after t119 and MUST re-pin this measured value; the stale 2484e65c pin is RED at base and the re-pin is this card's owned surface"; exit 1; }
grep -qF "$RD_IF" backend/scripts/docs_verification.py || { echo "ac2 RED: CARRIED_DIGESTS still pins infra_verification.md at a value other than the committed report ($RD_IF) - t119's regeneration moved it and t111 re-pins by measurement"; exit 1; }
grep -qE "^CARRIED_REPORT PASS file=docs/criteria/infra_verification.md rows=24$" "$G" || { echo "ac2 RED: the committed report does not attest the infra carried row (rows=24) - with both re-pins absorbed the regenerated report must print it"; exit 1; }
# determinism (t94/t96 ac3 pattern): regeneration on the candidate must be a no-op
export PATH="$HOME/.local/bin:$PATH"
command -v uv >/dev/null 2>&1 || { echo "ac2 RED: uv unavailable - the determinism leg cannot run"; exit 1; }
B=$(mktemp) || { echo "ac2 RED: mktemp failed"; exit 1; }
cp "$G" "$B"
(cd backend && PYTHONPATH=. uv run python scripts/docs_verification.py >/dev/null 2>&1); RC=$?
cmp -s "$G" "$B" || { echo "ac2 RED: regenerating docs_verification.md changed its bytes on the candidate - the committed report must already BE the deterministic output of these exact bytes"; cp "$B" "$G"; rm -f "$B"; exit 1; }
cp "$B" "$G"; rm -f "$B"
[ "$RC" = "0" ] || { echo "ac2 RED: docs_verification.py exited $RC on the candidate - with the CARRIED re-pins absorbed the generator must be fully GREEN on this card's candidate (every CARRIED and STORED gate it re-attests has its pin moved to the t119-regenerated bytes by this card)"; exit 1; }
echo "ac2 GREEN: RE-PIN NUMBER ONE SETTLED BY MEASUREMENT - lines=$CL digest=$CD agree between the candidate, the two README constants and the regenerated deterministic report (regeneration is a byte-exact no-op and the generator exits 0); the two CARRIED_DIGESTS re-pins equal the committed agent_pack ($RD_AP) and infra ($RD_IF) reports; the REQ-DOC-010 row and the link check are green; the envelope holds ($CL lines <= 400, 17 H2, all-CRLF, ASCII, unchanged REQ-id set, 13 hex literals)"

verification_commands.ac3:
set -u
test -f docs/state/merge_test_index.json || { echo "ac3 RED: docs/state/merge_test_index.json missing"; exit 1; }
command -v python3 >/dev/null || { echo "ac3 RED: python3 missing"; exit 1; }
python3 -c "import json;json.load(open('docs/state/merge_test_index.json',encoding='utf-8'))" || { echo "ac3 RED: the merge test index is not parseable JSON"; exit 1; }
ex(){ python3 -c "import json,sys;sys.stdout.write(json.load(open('docs/state/merge_test_index.json',encoding='utf-8'))['tests'][int(sys.argv[1])]['command'])" "$1"; }
mkdir -p build/t111 || { echo "ac3 RED: cannot create build/t111"; exit 1; }
N=0
for i in 27 119 128 135 144 149 201 210 243 245 249 251 252 253 255 256 232 250; do
  ex "$i" > "build/t111/gate_$i.sh" || { echo "ac3 RED: stored gate tests[$i] could not be extracted"; exit 1; }
  S=$(wc -c < "build/t111/gate_$i.sh" | tr -dc "0-9"); [ "${S:-0}" -ge 200 ] || { echo "ac3 RED: extracted tests[$i] is ${S:-0} bytes - an empty extraction would make the replay vacuous"; exit 1; }
  OUT=$(bash "build/t111/gate_$i.sh" 2>&1); RC=$?
  if [ "$RC" != 0 ]; then
    echo "ac3 RED: carried stored gate tests[$i] exited $RC against the t111 candidate - it was GREEN at the merge base and this card may not break it; its last output line follows"
    printf "%s\n" "$OUT" | tail -1
    exit 1
  fi
  N=$((N+1))
done
[ "$N" = "18" ] || { echo "ac3 RED: only $N of 18 carried gates were replayed"; exit 1; }
rm -rf build/t111
echo "ac3 evidence: 18 carried README-scoped gates (27 119 128 135 144 149 201 210 243 245 249 251 252 253 255 256 plus the t96 coordinated set 232 250) replayed VERBATIM from the index and all GREEN - Quick Start is untouched by t111, so the t96 set needs no second amendment"
if git rev-parse --git-dir >/dev/null 2>&1; then
  git diff --name-only HEAD | grep -qx "docs/state/merge_test_index.json" && { echo "ac3 RED: the builder edited docs/state/merge_test_index.json - the index is orchestrator-owned; t111 PROPOSES the tests[227] settlement and writes ZERO index bytes"; exit 1; }
  git diff --name-only HEAD | grep -qx "openapi.yaml" && { echo "ac3 RED: openapi.yaml is byte-frozen and changed"; exit 1; }
fi
echo "ac3 GREEN: REGRESSION GATE - 18 carried README-scoped gates replay GREEN verbatim, the t96 coordinated set 232/250/251 is unchanged by this card, and the index and openapi.yaml carry zero bytes from this card"

verification_commands.ac4:
set -u
test -f docs/state/merge_test_index.json || { echo "ac4 RED: docs/state/merge_test_index.json missing"; exit 1; }
command -v python3 >/dev/null || { echo "ac4 RED: python3 missing"; exit 1; }
python3 - <<'PYEOF' || exit 1
import hashlib, json, os, sys
A = "docs/state/outputs/t111_definer_gate_amendment.json"
if not os.path.exists(A):
    sys.stderr.write("ac4 RED: %s missing - t111 ships exactly one settlement record for tests[227] and no merge window can apply it without it\n" % A)
    raise SystemExit(1)
rec = json.load(open(A, encoding="utf-8"))
if rec.get("card") != "t111":
    sys.stderr.write("ac4 RED: the settlement record does not belong to card t111\n"); raise SystemExit(1)
if rec.get("authority") != "recorded orchestrator ruling (t71 retired-pin settlement precedent; operator directive 'all of them must be fixed', WAL 1267)":
    sys.stderr.write("ac4 RED: the record must name its authority verbatim - a definer may not settle a stale pin on its own authority\n"); raise SystemExit(1)
if rec.get("applied_by") != "orchestrator" or rec.get("card_writes_index_bytes") is not False:
    sys.stderr.write("ac4 RED: the record must declare applied_by=orchestrator and card_writes_index_bytes=false\n"); raise SystemExit(1)
if rec.get("policy") != "W2 eight-property index-amendment policy (WAL 1248), invoked IN WRITING":
    sys.stderr.write("ac4 RED: the record must state IN WRITING that the W2 eight-property policy is invoked - the settlement changes index bytes and cannot be implicit\n"); raise SystemExit(1)
am = rec.get("amendments", [])
if len(am) != 1 or int(am[0].get("index", -1)) != 227:
    sys.stderr.write("ac4 RED: t111 ships exactly one settlement targeting tests[227], found %s\n" % [e.get("index") for e in am]); raise SystemExit(1)
e = am[0]
stale = e.get("stale_premises", [])
need = {"README.md", "render.yaml", "docs/criteria/docs_verification.md", ".github/workflows directory listing"}
if not need.issubset(set(stale)):
    sys.stderr.write("ac4 RED: the record must price every stale premise by name; %s missing (measured at survey: README 308/a64efaa2, render.yaml 60110dd0 vs shipped 92c75305, report 29d22aff, and the workflows listing that t119's promote.yml invalidates)\n" % sorted(need - set(stale))); raise SystemExit(1)
if e.get("re_premise_not_relax") is not True:
    sys.stderr.write("ac4 RED: the record must declare re_premise_not_relax true - the settlement re-premises leg 227 to the then-shipped bytes; relaxing or deleting it is forbidden\n"); raise SystemExit(1)
idx = json.load(open("docs/state/merge_test_index.json", encoding="utf-8"))["tests"]
t = idx[str(227)] if isinstance(idx, dict) else idx[227]
cmd = t["command"]
cmd_sha = hashlib.sha256(cmd.encode("utf-8")).hexdigest()
entry_sha = hashlib.sha256(json.dumps(t, separators=(",", ":")).encode("utf-8")).hexdigest()
regions = e.get("replaced_regions", [])
if not regions:
    sys.stderr.write("ac4 RED: the settlement carries no replaced_regions - the edit must be reconstructible byte-for-byte\n"); raise SystemExit(1)
def apply_regions(src, pairs, direction):
    out = src
    for r in pairs:
        needle = r["from"] if direction == "forward" else r["to"]
        repl = r["to"] if direction == "forward" else r["from"]
        if out.count(needle) != 1:
            sys.stderr.write("ac4 RED: a replaced_region %s text is not unique in the shipped tests[227] command - the record does not describe the shipped bytes\n" % ("from" if direction == "forward" else "to")); raise SystemExit(1)
        out = out.replace(needle, repl, 1)
    return out
nc = e.get("negative_control_matrix", [])
if len(nc) < 5:
    sys.stderr.write("ac4 RED: the settlement needs at least five negative-control legs, found %d\n" % len(nc)); raise SystemExit(1)
bad = [x.get("case") for x in nc if x.get("measured_rc") != x.get("expected_rc")]
if bad:
    sys.stderr.write("ac4 RED: negative-control legs not as expected: %s\n" % bad); raise SystemExit(1)
if "a64efaa2406a22fcab1e18c1564035caf6ff8d24c85b1d8f92817202e6c0d73c" not in cmd:
    sys.stderr.write("ac4 RED: the shipped tests[227] no longer carries the stale pin-2 README digest - the premise of this settlement has changed; STOP and request a re-groom rather than guessing bytes\n"); raise SystemExit(1)
if cmd_sha == e["old_command_sha256"]:
    if entry_sha != e.get("entry_sha_before"):
        sys.stderr.write("ac4 RED: the index still holds the OLD tests[227] command but the entry sha moved - the entry was edited outside the record\n"); raise SystemExit(1)
    built = apply_regions(cmd, regions, "forward")
    if hashlib.sha256(built.encode("utf-8")).hexdigest() != e.get("new_command_sha256"):
        sys.stderr.write("ac4 RED: applying the replaced_regions forward does not reproduce new_command_sha256 - the record does not describe the intended edit\n"); raise SystemExit(1)
    if apply_regions(built, regions, "reverse") != cmd:
        sys.stderr.write("ac4 RED: reversing the replaced_regions out of the built command does not reproduce the shipped command - the record is not lossless\n"); raise SystemExit(1)
    state = "pre-settlement (index bytes unchanged; the record reconstructs the intended edit both ways)"
elif cmd_sha == e["new_command_sha256"]:
    if entry_sha != e.get("entry_sha_after"):
        sys.stderr.write("ac4 RED: the index holds the SETTLED tests[227] command but not the recorded entry sha - the settled entry drifted from the record\n"); raise SystemExit(1)
    if apply_regions(cmd, regions, "reverse") == cmd:
        sys.stderr.write("ac4 RED: reversing the replaced_regions out of the SETTLED command changed nothing - the record does not describe the shipped bytes\n"); raise SystemExit(1)
    state = "post-settlement (the orchestrator has applied the record; entry sha matches the recorded pin)"
else:
    sys.stderr.write("ac4 RED: the shipped tests[227] command sha %s matches NEITHER old_command_sha256 nor new_command_sha256 - the index drifted under the settlement\n" % cmd_sha[:16]); raise SystemExit(1)
if "6f2a0a3d05680b4dd44f427c852b8ffca29b6a2dfbd54f9a582a54796a949354" not in (apply_regions(cmd, regions, "forward") if state.startswith("pre") else cmd):
    sys.stderr.write("ac4 RED: the settlement dropped the openapi.yaml pin - leg 227's openapi half is GREEN and load-bearing; the settlement re-premises the stale halves and keeps this one verbatim\n"); raise SystemExit(1)
PH = ["<README_CANDIDATE_DIGEST_64HEX>", "<README_CANDIDATE_LINES>", "<RENDER_YAML_CR_STRIPPED_DIGEST_64HEX>", "<DOCS_VERIFICATION_REPORT_CR_STRIPPED_DIGEST_64HEX>"]
unresolved = [p for p in PH if any(p in json.dumps(r) for r in regions)]
if unresolved:
    sys.stderr.write("ac4 RED: the settlement record still carries unresolved placeholders %s - the builder must substitute the ac2-MEASURED candidate digest, the measured line count, the shipped render.yaml cr-stripped digest and the regenerated report digest into replaced_regions, then recompute new_command_sha256 and entry_sha_after (the record's placeholder_protocol); this fence re-verifies the substitution by reconstruction, so copying a number from a card cannot pass\n" % unresolved); raise SystemExit(1)
sys.stdout.write("ac4 GREEN: TESTS[227] SETTLEMENT RECORD SOUND - one record at %s for card t111 targeting tests[227], authority recorded as an orchestrator ruling under the t71 precedent, the W2 eight-property policy invoked IN WRITING, all four stale premises priced by name, the openapi half preserved verbatim, the regions reconstruct the edit byte-for-byte in the %s state, the four measured pins substituted (no unresolved placeholders), and all %d negative-control legs as-expected\n" % (A, state, len(nc)))
PYEOF

verification_commands.ac5:
