test -f docs/issues/t111.md || { echo "ac5 RED: docs/issues/t111.md missing - the ruling lives in the card"; exit 1; }
C=$(tr -d '\r' < docs/issues/t111.md)
printf "%s\n" "$C" | grep -qiE "^#+[[:space:]].*(recorded orchestrator ruling)" || { echo "ac5 RED: the card has no 'Recorded orchestrator ruling' section - the t71 retired-pin settlement precedent settles a stale pin only by a RECORDED ruling, never by a definer's unilateral decision"; exit 1; }
R=$(printf "%s\n" "$C" | awk '/^#+[[:space:]].*[Rr]ecorded orchestrator ruling/{f=1;next} f&&/^## /{exit} f')
[ -n "$R" ] || { echo "ac5 RED: the ruling section is empty"; exit 1; }
printf "%s\n" "$R" | grep -qE "tests\[227\]" || { echo "ac5 RED: the ruling does not name tests\[227\]"; exit 1; }
printf "%s\n" "$R" | grep -qiE "index bytes (do|will)[[:space:]]+(change|move)|index bytes (do not|do not change|unchanged)" || { echo "ac5 RED: the ruling must state EXPLICITLY whether index bytes change - the brief requires the disclosure either way"; exit 1; }
printf "%s\n" "$R" | grep -qiE "W2 eight-property|eight-property policy" || { echo "ac5 RED: the ruling must invoke the W2 eight-property amendment policy IN WRITING when index bytes change (the operator directive 'all of them must be fixed' authorizes the fix, not a silent exception to the policy)"; exit 1; }
printf "%s\n" "$R" | grep -qiE "propose|proposal|applied by the orchestrator|orchestrator applies" || { echo "ac5 RED: the ruling must state that the card PROPOSES and the orchestrator APPLIES the index edit"; exit 1; }
printf "%s\n" "$R" | grep -qiE "re-premise|re-premised" || { echo "ac5 RED: the ruling must say the leg is RE-PREMISED to the then-shipped bytes, never relaxed or deleted"; exit 1; }
printf "%s\n" "$R" | grep -qiE "t71" || { echo "ac5 RED: the ruling must cite its precedent (t71 retired-pin settlement)"; exit 1; }
printf "%s\n" "$R" | grep -qiE "232|250|251" && { echo "ac5 RED: NEGATIVE CONTROL - the ruling section must not be a copy of the t96 coordinated-set text; Quick Start legs 232/250/251 are measured unchanged by this card and belong in ac3, not in the ruling"; exit 1; }
echo "ac5 GREEN: RECORDED ORCHESTRATOR RULING PRESENT - the card settles tests[227] in writing under the t71 precedent, discloses the index-byte consequence, invokes the W2 eight-property policy explicitly, re-premises rather than relaxes, and leaves the index edit to the orchestrator"
